#include "resident/checkpoint/projection_writer.hpp"
// 公务报价与回执的中央边界只转换显式typed值；解码不执行授职或重新生成事实。
#include "resident/kernel/politics_integration.hpp"
#include "politics_fiscal.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
#include <set>
#include <limits>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;
// 重复、未知和缺失字段分别在同一入口拒绝，不容许另一套宽松回执格式。
void exact(const V& v,std::initializer_list<const char*> fields,const StableId& path){std::set<StableId> pending;for(const auto* f:fields)pending.insert(f);for(const auto& row:boundary::object(v,path))if(!pending.erase(row.first))boundary::fail("InvalidPoliticsBoundaryField",path+"/"+row.first);if(!pending.empty())boundary::fail("MissingPoliticsBoundaryField",path+"/"+*pending.begin());}
// 执行代和世界ID一起冻结，读档后不能拿旧界面的报价指向新候选。
V identity(const WorldIdentity& value){StableId hex;const char* digits="0123456789abcdef";for(const auto byte:value.world_id){hex+=digits[byte>>4];hex+=digits[byte&15];}return boundary::obj({{"world_id",V{hex}},{"execution_epoch",V{value.execution_epoch}},{"revision",V{value.revision}},{"tick",V{value.tick}}});}
WorldIdentity identity(const V& value){exact(value,{"world_id","execution_epoch","revision","tick"},"/identity");WorldIdentity out;const auto hex=boundary::get_string(value,"world_id","/identity");if(hex.size()!=32)boundary::fail("InvalidPoliticsWorldIdentity","/identity/world_id");auto nibble=[](char c)->Integer{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;return -1;};for(std::size_t n=0;n<out.world_id.size();++n){const auto hi=nibble(hex[n*2]),lo=nibble(hex[n*2+1]);if(hi<0||lo<0)boundary::fail("InvalidPoliticsWorldIdentity","/identity/world_id");out.world_id[n]=static_cast<std::uint8_t>(hi*16+lo);}out.execution_epoch=boundary::get_int(value,"execution_epoch","/identity");out.revision=boundary::get_int(value,"revision","/identity");out.tick=boundary::get_int(value,"tick","/identity");if(out.execution_epoch<0||out.revision<0||out.tick<0)boundary::fail("InvalidPoliticsWorldIdentity","/identity");return out;}
StableId resource_kind(ResourceKey::Kind kind){switch(kind){case ResourceKey::Kind::actor:return "actor";case ResourceKey::Kind::wallet:return "wallet";case ResourceKey::Kind::inventory:return "inventory";default:boundary::fail("UnsupportedPoliticsQuoteResource",{});}return {};}
ResourceKey::Kind resource_kind(const StableId& kind){if(kind=="actor")return ResourceKey::Kind::actor;if(kind=="wallet")return ResourceKey::Kind::wallet;if(kind=="inventory")return ResourceKey::Kind::inventory;boundary::fail("UnsupportedPoliticsQuoteResource",kind);return ResourceKey::Kind::actor;}
}
BoundaryValue encode_politics_quote(const PoliticsQuote& quote){V::Array versions;for(const auto& r:quote.resource_versions){if(r.version>static_cast<std::uint64_t>(std::numeric_limits<Integer>::max()))boundary::fail("PoliticalReadVersionOverflow",r.resource.id);versions.push_back(boundary::obj({{"kind",V{resource_kind(r.resource.kind)}},{"id",V{r.resource.id}},{"version",V{static_cast<Integer>(r.version)}}}));}return boundary::obj({{"identity",identity(quote.identity)},{"actor_id",V{quote.actor_id}},{"duration",V{quote.duration}},{"command_kind",V{politics_command_kind(quote.command)}},{"command",encode_politics_command(quote.command)},{"resource_versions",V{std::move(versions)}}});}
Outcome<PoliticsQuote> decode_politics_quote(const BoundaryValue& value){try{exact(value,{"identity","actor_id","duration","command_kind","command","resource_versions"},"/quote");PoliticsQuote out;out.identity=identity(boundary::field(value,"identity","/quote"));out.actor_id=boundary::get_string(value,"actor_id","/quote");out.duration=boundary::get_int(value,"duration","/quote");if(out.actor_id.empty()||out.duration!=0)boundary::fail("InvalidPoliticsQuote","/quote");auto command=decode_politics_command(boundary::get_string(value,"command_kind","/quote"),boundary::field(value,"command","/quote"));if(!command.ok)return {false,{},command.error};out.command=std::move(command.value);std::set<std::pair<ResourceKey::Kind,StableId>> seen;for(const auto& v:boundary::array(boundary::field(value,"resource_versions","/quote"),"/quote/resource_versions")){exact(v,{"kind","id","version"},"/resource_version");ReadVersion r;r.resource.kind=resource_kind(boundary::get_string(v,"kind","/resource_version"));r.resource.id=boundary::get_string(v,"id","/resource_version");const auto version=boundary::get_int(v,"version","/resource_version");if(r.resource.id.empty()||version<0||!seen.insert({r.resource.kind,r.resource.id}).second)boundary::fail("InvalidPoliticsReadVersion","/resource_version");r.version=static_cast<std::uint64_t>(version);out.resource_versions.push_back(std::move(r));}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 财政报价复用本域严格世界身份与资源版本协议，只允许具名税政命令。
BoundaryValue encode_political_fiscal_quote(const PoliticalFiscalQuote& quote){V::Array versions;for(const auto& r:quote.resource_versions){if(r.version>static_cast<std::uint64_t>(std::numeric_limits<Integer>::max()))boundary::fail("PoliticalReadVersionOverflow",r.resource.id);versions.push_back(boundary::obj({{"kind",V{resource_kind(r.resource.kind)}},{"id",V{r.resource.id}},{"version",V{static_cast<Integer>(r.version)}}}));}return boundary::obj({{"identity",identity(quote.identity)},{"actor_id",V{quote.actor_id}},{"duration",V{quote.duration}},{"command_kind",V{"political_set_tax"}},{"command",encode_political_set_tax(quote.command)},{"resource_versions",V{std::move(versions)}}});}
Outcome<PoliticalFiscalQuote> decode_political_fiscal_quote(const BoundaryValue& value){try{exact(value,{"identity","actor_id","duration","command_kind","command","resource_versions"},"/quote");PoliticalFiscalQuote out;out.identity=identity(boundary::field(value,"identity","/quote"));out.actor_id=boundary::get_string(value,"actor_id","/quote");out.duration=boundary::get_int(value,"duration","/quote");if(out.actor_id.empty()||out.duration!=0)boundary::fail("InvalidPoliticalFiscalQuote","/quote");if(boundary::get_string(value,"command_kind","/quote")!="political_set_tax")boundary::fail("InvalidPoliticalFiscalQuote","/quote/command_kind");auto command=decode_political_set_tax(boundary::field(value,"command","/quote"));if(!command.ok)return {false,{},command.error};out.command=std::move(command.value);std::set<std::pair<ResourceKey::Kind,StableId>> seen;for(const auto& v:boundary::array(boundary::field(value,"resource_versions","/quote"),"/quote/resource_versions")){exact(v,{"kind","id","version"},"/resource_version");ReadVersion r;r.resource.kind=resource_kind(boundary::get_string(v,"kind","/resource_version"));r.resource.id=boundary::get_string(v,"id","/resource_version");const auto version=boundary::get_int(v,"version","/resource_version");if(r.resource.id.empty()||version<0||!seen.insert({r.resource.kind,r.resource.id}).second)boundary::fail("InvalidPoliticsReadVersion","/resource_version");r.version=static_cast<std::uint64_t>(version);out.resource_versions.push_back(std::move(r));}return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 同一字段路径供原JSON编码与checkpoint形状核验使用。
Status emit_politics_effects_fields(ProjectionWriter& w,const PoliticsEffects& value){w.field("appointment_id",value.appointment_id);w.sequence("fact_ids",value.fact_ids,[](auto& child,const auto& id){return child.field("",id);});w.sequence("receipt_ids",value.receipt_ids,[](auto& child,const auto& id){return child.field("",id);});return w.status();}
BoundaryValue encode_politics_effects(const PoliticsEffects& value){BoundaryValue result;BoundaryProjectionWriter writer(result);auto status=writer.object("",[&](auto& fields){return emit_politics_effects_fields(fields,value);});if(status.ok)status=writer.finish();if(!status.ok)boundary::fail(status.error.original.code,status.error.original.path);return result;}
Outcome<PoliticsEffects> decode_politics_effects(const BoundaryValue& value){try{exact(value,{"appointment_id","fact_ids","receipt_ids"},"/effects");PoliticsEffects out;out.appointment_id=boundary::get_string(value,"appointment_id","/effects");out.fact_ids=boundary::strings(boundary::field(value,"fact_ids","/effects"),"/effects/fact_ids");out.receipt_ids=boundary::strings(boundary::field(value,"receipt_ids","/effects"),"/effects/receipt_ids");return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit_politics_effects(CodecVisitor& c,PoliticsEffects& value){c.field("appointment_id",value.appointment_id);c.sequence("fact_ids",value.fact_ids,[](auto& codec,auto& id){return codec.field("id",id);});c.sequence("receipt_ids",value.receipt_ids,[](auto& codec,auto& id){return codec.field("id",id);});return c.status();}
} // 回执的业务真实性必须再由validate_politics_receipt_source对照实际事实链核验。
